 const people=names.map(([id,name,classId,tone,baseXp,rhythm])=>({id,name,classId,tone,baseXp,rhythm,enrolled:classId==='aurora'?'2026-07-24':'2026-09-03',email:'',goal:'Ganhar confiança na construção e manter uma rotina de estudos.',note:'',status:'active',demo:true}));
 const attendance={};
 for(const lesson of lessons.filter(item=>item.done&&item.type==='regular')){
  attendance[lesson.id]={};people.filter(person=>person.classId===lesson.classId).forEach((person,index)=>{const number=Number(lesson.id.split('-').pop());attendance[lesson.id][person.id]=(person.id==='theo'&&[3,6,7,8].includes(number))||(person.id==='pedro'&&number===8)?'absent':index===2&&number===5?'excused':'present';});
 }
 const assignments=[{id:'task-light',classId:'aurora',lessonId:'aurora-9',title:'Uma fonte de luz, três valores',description:'Construa volumes simples e separe luz, meio-tom e sombra. Observe a forma antes do acabamento.',due:'2026-09-24',steps:taskItems.map(([title])=>({id:uid('step'),title})),rhythms:{adventure:2,hero:4,mercenary:6}}, {id:'task-shapes',classId:'aurora',lessonId:'aurora-8',title:'Fusão de formas',description:'Combine duas formas simples em uma construção coerente.',due:'2026-09-17',steps:[{id:'forms-1',title:'Construir duas massas'},{id:'forms-2',title:'Integrar volumes com cortes claros'},{id:'forms-3',title:'Variar a combinação'},{id:'forms-4',title:'Revisar os eixos'}],rhythms:{adventure:1,hero:2,mercenary:4}}, {id:'task-heads',classId:'eclipse',lessonId:'eclipse-3',title:'Cabeça em três ângulos',description:'Mantenha a relação entre os planos ao girar a cabeça.',due:'2026-09-23',steps:[{id:'heads-1',title:'Marcar eixos e proporção'},{id:'heads-2',title:'Construir os planos'},{id:'heads-3',title:'Girar para um novo ângulo'},{id:'heads-4',title:'Revisar a proporção'}],rhythms:{adventure:1,hero:2,mercenary:4}}];
 const deliveries=[['demo-lia','lia','task-light','volumes','Primeira leitura dos planos','pending',0],['demo-pedro','pedro','task-light','volumes','Volumes e sombra projetada','pending',0],['demo-bia','bia','task-light','heads','Estudo de luz na cabeça','approved',80],['demo-theo','theo','task-shapes','figure','Revisão da construção','revision',20],['demo-lia-old','lia','task-shapes','figure','Integração de massas','approved',60],['demo-pedro-old','pedro','task-shapes','volumes','Formas combinadas','approved',40],['demo-bia-old','bia','task-shapes','figure','Variação de volumes','approved',80],['demo-marina','marina','task-heads','heads','Giro e estrutura da cabeça','pending',0]].map(([id,studentId,assignmentId,imageRef,title,status,xp])=>({id,studentId,classId:people.find(person=>person.id===studentId).classId,assignmentId,imageRef,title,demo:true,task:true,date:assignmentId==='task-shapes'?'2026-09-16T19:30:00':'2026-09-18T14:00:00',note:'Registro fictício para experimentar o fluxo. A imagem é uma referência do acervo Xuim Art.',review:status==='pending'?null:{status,xp,criteria:{construction:status==='revision'?1:3,values:2,clarity:status==='revision'?1:2},feedback:status==='revision'?'Volte aos eixos principais e simplifique as massas antes de detalhar.':'A estrutura está clara. No próximo estudo, procure separar os valores com mais intenção.',date:'2026-09-18T15:00:00'}}));
