function saveSchool(message){const saved=persist();syncSchoolChrome();if(message)toast(saved?message:'Alteração disponível nesta sessão. Exporte seus testes: o armazenamento está indisponível.');return saved;}
function logSchool(text,studentId=''){school().activity.unshift({id:uid('activity'),text,studentId,classId:currentClass().id,date:new Date().toISOString()});school().activity=school().activity.slice(0,100);}
function studentAttendance(student){
 const eligible=school().lessons.filter(lesson=>lesson.classId===student.classId&&lesson.done&&lesson.type==='regular'&&lesson.date>=student.enrolled);
 const statuses=eligible.map(lesson=>school().attendance[lesson.id]?.[student.id]||'unset');const registered=statuses.filter(status=>status!=='unset'&&status!=='excused');const present=registered.filter(status=>status==='present').length;
 return {eligible,statuses,present,count:registered.length,percent:registered.length?Math.round(present/registered.length*100):null,unrecorded:statuses.filter(status=>status==='unset').length};
}
function studentXP(student){
 if(!student)return 0;
 const evaluated=latestDeliveries(studentDeliveries(student.id).filter(item=>item.review)).reduce((sum,item)=>sum+asNumber(item.review?.xp),0);
 const practice=Object.entries(school().progress).filter(([key])=>key.startsWith(student.id+'|')).reduce((sum,[key,value])=>{const assignment=school().assignments.find(item=>item.id===key.slice(student.id.length+1));return sum+new Set((value.checks||[]).filter(id=>assignment?.steps.some(step=>step.id===id))).size*20;},0);
 return asNumber(student.baseXp)+evaluated+practice;
}
function studentAttention(student){
 const attendance=studentAttendance(student);if(attendance.percent!==null&&attendance.percent<75)return 'Presença abaixo de 75%';
 const pending=school().assignments.filter(item=>item.classId===student.classId&&item.due<SCENARIO_DATE&&school().lessons.find(lesson=>lesson.id===item.lessonId)?.date>=student.enrolled&&!studentDeliveries(student.id).some(delivery=>delivery.assignmentId===item.id));
 return pending.length?'Tarefa vencida sem entrega':'';
}
function progressFor(student,assignment){const key=student.id+'|'+assignment.id;return school().progress[key]||(school().progress[key]={rhythm:student.rhythm||'hero',checks:[]});}
function metrics(){const people=classStudents(),deliveries=classDeliveries(),attendance=people.map(studentAttendance);const present=attendance.reduce((n,item)=>n+item.present,0),count=attendance.reduce((n,item)=>n+item.count,0);return {people:people.length,pending:latestDeliveries(deliveries).filter(item=>deliveryStatus(item)==='pending').length,reviewed:deliveries.filter(item=>item.review).length,presence:count?Math.round(present/count*100):null,attention:people.filter(studentAttention).length};}
