 $('#export-backup').onclick=()=>{const blob=new Blob([JSON.stringify({format:'xuim-atelier',schema:2,exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob);download(url,'xuim-atelie-testes-'+localDate()+'.json');setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Cópia dos testes exportada.');};$('#import-backup').onclick=()=>$('#backup-file').click();
