function validateBackup(data){
 const fail=()=>{throw new Error('Esta cópia não é compatível ou contém registros inválidos.');};
 if(data?.format!=='xuim-atelier'||data.schema!==2||data.state?.version!==1||data.state.school?.version!==2)fail();
 const next=data.state,s=next.school,text=value=>typeof value==='string',list=(value,max=1000)=>Array.isArray(value)&&value.length<=max,date=value=>text(value)&&/^\d{4}-\d{2}-\d{2}$/.test(value)&&!Number.isNaN(new Date(value+'T12:00:00').getTime()),safeObject=value=>value&&typeof value==='object'&&!Array.isArray(value),id=value=>text(value)&&/^[a-zA-Z0-9_-]{1,100}$/.test(value);
 const rejectKeys=value=>{if(value&&typeof value==='object')for(const key of Object.keys(value)){if(['__proto__','constructor','prototype'].includes(key))fail();rejectKeys(value[key]);}};rejectKeys(next);
 if(!list(s.classes,50)||!s.classes.length||!list(s.students,500)||!list(s.lessons)||!list(s.assignments,200)||!list(s.deliveries,500)||!safeObject(s.attendance)||!safeObject(s.progress)||!list(s.activity,100)||!list(next.submissions,15)||!list(next.messages,80)||!safeObject(next.feedback)||!list(next.strokes,300))fail();
 const unique=items=>new Set(items.map(item=>item?.id)).size===items.length;
 for(const items of [s.classes,s.students,s.lessons,s.assignments,s.deliveries,next.submissions])if(!unique(items))fail();
 if(!unique([...s.deliveries,...next.submissions]))fail();
 const classes=new Set(s.classes.map(item=>item.id)),studentsIds=new Set(s.students.map(item=>item.id)),lessonIds=new Set(s.lessons.map(item=>item.id)),assignmentIds=new Set(s.assignments.map(item=>item.id));
 for(const item of s.classes)if(!id(item.id)||![item.name,item.course,item.teacher,item.description].every(text))fail();
 for(const item of s.students)if(!id(item.id)||!classes.has(item.classId)||![item.name,item.email,item.goal,item.note].every(text)||!date(item.enrolled)||!['active','archived'].includes(item.status)||!Object.hasOwn(rhythms,item.rhythm)||!['pink','green','purple','amber',''].includes(item.tone)||!Number.isFinite(item.baseXp)||item.baseXp<0)fail();
 for(const item of s.lessons)if(!id(item.id)||!classes.has(item.classId)||!Object.hasOwn(lessonTypes,item.type)||![item.title,item.module,item.description,item.note].every(text)||!date(item.date)||!/^\d{2}:\d{2}$/.test(item.time)||!Number.isFinite(item.duration)||typeof item.done!=='boolean')fail();
 for(const item of s.assignments)if(!id(item.id)||!classes.has(item.classId)||!lessonIds.has(item.lessonId)||![item.title,item.description].every(text)||!date(item.due)||!list(item.steps,12)||!item.steps.length||!unique(item.steps)||!item.steps.every(step=>id(step.id)&&text(step.title))||!safeObject(item.rhythms)||!Object.keys(rhythms).every(key=>Number.isInteger(item.rhythms[key])&&item.rhythms[key]>=1&&item.rhythms[key]<=item.steps.length))fail();
 for(const item of [...s.deliveries,...next.submissions]){if(!id(item.id)||!classes.has(item.classId)||!studentsIds.has(item.studentId)||![item.title,item.note,item.date].every(text)||!(validImage(item.image)||references.some(ref=>ref.id===item.imageRef))||(item.assignmentId&&!assignmentIds.has(item.assignmentId)))fail();if(item.correction&&!validImage(item.correction))fail();if(item.review&&(!['approved','revision'].includes(item.review.status)||!text(item.review.feedback)||!Number.isFinite(item.review.xp)||item.review.xp<0||item.review.xp>200||!safeObject(item.review.criteria)||!assessmentCriteria.every(([key])=>Number.isInteger(item.review.criteria[key])&&item.review.criteria[key]>=1&&item.review.criteria[key]<=3)))fail();}
 for(const [lessonId,records] of Object.entries(s.attendance))if(!lessonIds.has(lessonId)||!safeObject(records)||!Object.entries(records).every(([studentId,status])=>studentsIds.has(studentId)&&Object.hasOwn(attendanceLabels,status)))fail();
 for(const [key,progress] of Object.entries(s.progress)){const [studentId,assignmentId]=key.split('|');if(!studentsIds.has(studentId)||!assignmentIds.has(assignmentId)||!safeObject(progress)||!Object.hasOwn(rhythms,progress.rhythm)||!list(progress.checks,12)||!progress.checks.every(id))fail();}
 if(!s.activity.every(item=>safeObject(item)&&text(item.text)&&text(item.date)&&classes.has(item.classId)))fail();
 if(!next.messages.every(item=>safeObject(item)&&text(item.text)&&text(item.time)&&['teacher','student'].includes(item.role)))fail();
 if(!Object.values(next.feedback).every(value=>list(value,100)&&value.every(item=>safeObject(item)&&text(item.text)&&['teacher','student'].includes(item.role))))fail();
 if(!next.strokes.every(stroke=>safeObject(stroke)&&['pen','eraser'].includes(stroke.tool)&&['#de2246','#29272d','#327abd'].includes(stroke.color)&&Number.isFinite(stroke.size)&&stroke.size>0&&list(stroke.points,20000)&&stroke.points.every(point=>list(point,2)&&point.length===2&&point.every(number=>Number.isFinite(number)&&number>=-10&&number<=10))))fail();
 if(next.customBoard&&(!validImage(next.customBoard.image)||!text(next.customBoard.title)))fail();
 if(!references.some(item=>item.id===next.boardKey)||!['teacher','student'].includes(next.role)||!classes.has(s.activeClass))fail();
 if(!validateAtelierBackup(next.atelier))fail();
 return next;
}
async function importBackup(event){
 const file=event.target.files[0];event.target.value='';if(!file)return;if(file.size>25*1024*1024){toast('A cópia precisa ter até 25 MB.');return;}
 try{const next=validateBackup(JSON.parse(await file.text()));openModal('Restaurar seus testes?',`<p class="form-intro">Esta cópia contém ${next.school.classes.length} turmas, ${next.school.students.length} alunos e ${next.submissions.length} imagens enviadas. Ela substituirá os registros atuais deste navegador.</p><p class="school-note">Se ainda não exportou a situação atual, cancele e use “Exportar meus testes” antes de continuar.</p>`,`<button class="btn" id="cancel-restore">Cancelar</button><button class="btn primary" id="confirm-restore">Restaurar esta cópia</button>`);$('#cancel-restore').onclick=()=>{closeModal();showBackup();};$('#confirm-restore').onclick=()=>{stopAtelier();state=next;closeModal();saveWarning=false;saveSchool('Cópia restaurada.');applyRole();updateReference();renderMessages();calendarMonth=(activeLesson()?.date||SCENARIO_DATE).slice(0,7);calendarDay='';navigate(state.role==='teacher'?'overview':'journey');};}
 catch(error){toast(error instanceof SyntaxError?'Não foi possível ler este arquivo JSON.':error.message);}
}

